import React, { useState, useEffect, useCallback } from 'react';
import { Dialog } from '@headlessui/react';
import { db } from '../../config/firebase';
import { useAuth } from '../../contexts/AuthContext';
import { 
  collection, 
  addDoc, 
  query, 
  where, 
  getDocs,
  doc,
  getDoc,
  updateDoc,
  serverTimestamp 
} from 'firebase/firestore';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { 
  Box, 
  Typography, 
  Button, 
  Paper,
  DialogTitle,
  DialogContent,
  DialogActions,
  Dialog as MuiDialog,
  TextField,
  IconButton,
  CircularProgress,
  Stack
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import { getCurrentShift } from '../../utils/shiftCalculator';


function Timer() {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [earlyMinutes, setEarlyMinutes] = useState(0);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [manualMinutes, setManualMinutes] = useState('');
  const [userTeam, setUserTeam] = useState(null);
  const [currentShift, setCurrentShift] = useState(null);
  const [timeEntryId, setTimeEntryId] = useState(null);
  const [hasStartedWork, setHasStartedWork] = useState(false);
  const [loading, setLoading] = useState(true);
  const { currentUser, loading: authLoading } = useAuth();
  const [isProcessing, setIsProcessing] = useState(false);
  const [manualEntryOpen, setManualEntryOpen] = useState(false);
  const [selectedDateTime, setSelectedDateTime] = useState(new Date());
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const fetchUserTeam = useCallback(async () => {
    if (!currentUser || authLoading) {
      return;
    }

    try {
      const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        setUserTeam(userData.team);
        const shift = getCurrentShift(userData.team);
        setCurrentShift(shift);
      }
    } catch (error) {
      console.error('Error fetching user team:', error);
    } finally {
      setLoading(false);
    }
  }, [currentUser, authLoading]);

  const checkExistingEntry = useCallback(async () => {
    if (!currentUser) {
      return;
    }

    const now = new Date();
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    const q = query(
      collection(db, 'timeEntries'),
      where('userId', '==', currentUser.uid),
      where('date', '>=', today)
    );

    try {
      const querySnapshot = await getDocs(q);
      if (!querySnapshot.empty) {
        const existingDoc = querySnapshot.docs[0];
        const existingData = existingDoc.data();
        setTimeEntryId(existingDoc.id);
        setHasStartedWork(true);
        
        // Always set the early minutes from the database
        const storedEarlyMinutes = existingData.earlyMinutes || 0;
        setEarlyMinutes(storedEarlyMinutes);
        setManualMinutes(storedEarlyMinutes.toString());
      }
    } catch (error) {
      console.error('Error checking existing entries:', error);
    }
  }, [currentUser]);

  // Add this useEffect to check existing entry when component mounts
  useEffect(() => {
    if (currentUser && !loading) {
      checkExistingEntry();
    }
  }, [currentUser, loading, checkExistingEntry]);

  // Update current time every second
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (currentUser && !authLoading) {
      fetchUserTeam();
      checkExistingEntry();
    }
  }, [currentUser, authLoading, fetchUserTeam, checkExistingEntry]);

  const calculateEarlyMinutes = (startTime, shiftStartTime) => {
    const [hours, minutes] = shiftStartTime.split(':').map(Number);
    
    // Create new date objects and set only hours and minutes
    const shiftStart = new Date(startTime);
    shiftStart.setHours(hours, minutes, 0, 0);
    
    const startTimeRounded = new Date(startTime);
    startTimeRounded.setSeconds(0, 0);
    
    // Get reset time (2 hours after shift start)
    const resetTime = new Date(shiftStart);
    resetTime.setHours(hours + 2, minutes, 0, 0);
    
    // If current time is past reset time, return 0
    if (startTimeRounded >= resetTime) {
      return 0;
    }
    
    return Math.floor((shiftStart - startTimeRounded) / (1000 * 60));
  };

  const handleStart = async () => {
    setIsProcessing(true);
    setError('');
    try {
      if (!currentUser || !userTeam || !currentShift) {
        setError('Missing required data. Please make sure your team is set in Settings.');
        return;
      }

      const now = new Date();
      const shiftStartTime = currentShift?.startTime;
      
      if (!shiftStartTime) {
        setError('Could not determine shift start time');
        return;
      }

      // Calculate early minutes
      const minutes = calculateEarlyMinutes(now, shiftStartTime);

      if (hasStartedWork && timeEntryId) {
        // Update existing entry with new early minutes
        await updateDoc(doc(db, 'timeEntries', timeEntryId), {
          earlyMinutes: minutes,
          earlyHours: Math.floor(minutes / 60 * 10) / 10,
          updatedAt: serverTimestamp()
        });
        
        setEarlyMinutes(minutes);
        setManualMinutes(minutes.toString());
        setSuccess('Early minutes updated successfully');
      } else {
        // Create new entry
        const entryData = {
          userId: currentUser.uid,
          date: now,
          startTime: now,
          earlyMinutes: minutes,
          earlyHours: Math.floor(minutes / 60 * 10) / 10,
          team: userTeam,
          shift: currentShift.name,
          createdAt: serverTimestamp(),
          type: 'auto'
        };

        const docRef = await addDoc(collection(db, 'timeEntries'), entryData);
        setTimeEntryId(docRef.id);
        setEarlyMinutes(minutes);
        setManualMinutes(minutes.toString());
        setHasStartedWork(true);
        setSuccess('Work started successfully');
      }
    } catch (error) {
      console.error('Error starting/updating work:', error);
      setError('Failed to start/update work: ' + error.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleEditMinutes = () => {
    if (!timeEntryId) {
      setError('No time entry found to edit');
      return;
    }
    setManualMinutes(earlyMinutes.toString());
    setDialogOpen(true);
  };

  const handleSaveTime = async () => {
    setIsProcessing(true);
    try {
      const minutes = parseInt(manualMinutes);
      if (isNaN(minutes) || minutes < 0) {
        setError('Please enter a valid number of minutes');
        return;
      }

      const hours = Math.floor(minutes / 60 * 10) / 10;
      
      if (!timeEntryId) {
        setError('No time entry found to update');
        return;
      }

      await updateDoc(doc(db, 'timeEntries', timeEntryId), {
        earlyMinutes: minutes,
        earlyHours: hours,
        updatedAt: serverTimestamp()
      });

      setEarlyMinutes(minutes);
      setDialogOpen(false);
      setSuccess('Time updated successfully');
    } catch (error) {
      console.error('Error saving time:', error);
      setError('Failed to save time: ' + error.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatTime = (date) => {
    return date.toLocaleTimeString('en-GB', { 
      hour: '2-digit', 
      minute: '2-digit', 
      second: '2-digit',
      hour12: false 
    });
  };

  const handleManualEntry = async () => {
    setIsProcessing(true);
    try {
      if (!currentUser || !userTeam || !currentShift) {
        setError('Missing required data. Please make sure your team is set in Settings.');
        return;
      }

      // Get the shift start time for the selected date
      const shiftStartTime = currentShift.startTime;
      if (!shiftStartTime) {
        setError('Could not determine shift start time');
        return;
      }

      // Calculate early minutes based on the selected date/time
      const minutes = calculateEarlyMinutes(selectedDateTime, shiftStartTime);
      
      // Check if an entry already exists for this date
      const startOfDay = new Date(selectedDateTime);
      startOfDay.setHours(0, 0, 0, 0);
      const endOfDay = new Date(selectedDateTime);
      endOfDay.setHours(23, 59, 59, 999);

      const q = query(
        collection(db, 'timeEntries'),
        where('userId', '==', currentUser.uid),
        where('date', '>=', startOfDay),
        where('date', '<=', endOfDay)
      );

      const existingEntries = await getDocs(q);

      if (!existingEntries.empty) {
        setError('An entry already exists for this date');
        return;
      }

      const entryData = {
        userId: currentUser.uid,
        date: selectedDateTime,
        startTime: selectedDateTime,
        earlyMinutes: minutes,
        earlyHours: Math.floor(minutes / 60 * 10) / 10, // Convert to hours and round to 1 decimal
        team: userTeam,
        shift: currentShift.name,
        createdAt: serverTimestamp(),
        type: 'manual'
      };

      const docRef = await addDoc(collection(db, 'timeEntries'), entryData);
      setTimeEntryId(docRef.id);
      setEarlyMinutes(minutes);
      setManualMinutes(minutes.toString());
      setHasStartedWork(true);
      setManualEntryOpen(false);
      setSuccess('Manual entry created successfully');
    } catch (error) {
      console.error('Error creating manual entry:', error);
      setError('Failed to create manual entry: ' + error.message);
    } finally {
      setIsProcessing(false);
    }
  };

  if (authLoading || loading) {
    return (
      <Box display="flex" justifyContent="center" mt={4}>
        <CircularProgress />
      </Box>
    );
  }

  if (!currentUser) {
    return (
      <Box display="flex" justifyContent="center" mt={4}>
        <Typography variant="h6">Please log in to access the timer</Typography>
      </Box>
    );
  }

  return (
    <div className="min-h-screen bg-white dark:bg-dark-900 text-gray-900 dark:text-gray-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {error && (
          <div className="mb-4 bg-red-50 dark:bg-red-900/30 border border-red-400 
            text-red-800 dark:text-red-300 rounded-md p-3 text-sm">
            {error}
          </div>
        )}

        {success && (
          <div className="mb-4 bg-green-50 dark:bg-green-900/30 border border-green-400 
            text-green-800 dark:text-green-300 rounded-md p-3 text-sm">
            {success}
          </div>
        )}

        {userTeam && currentShift && (
          <div className="bg-gray-50 dark:bg-dark-800 rounded-xl p-6 mb-8 shadow-lg 
            transform transition-all hover:scale-[1.02] mx-auto max-w-2xl">
            <h2 className="text-2xl sm:text-3xl font-bold mb-3 text-center">
              {userTeam} - {currentShift.name} Shift
            </h2>
            <p className="text-lg text-gray-600 dark:text-gray-300 text-center">
              Shift starts at {currentShift.startTime}
            </p>
            {hasStartedWork && (
              <div className="mt-6 flex items-center justify-center space-x-3">
                <span className="text-xl text-gray-700 dark:text-gray-200">
                  Early minutes: {earlyMinutes}
                </span>
                <button 
                  onClick={handleEditMinutes}
                  className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-dark-700
                    transform transition-all hover:scale-110 active:scale-95"
                >
                  <EditIcon className="w-6 h-6" />
                </button>
              </div>
            )}
          </div>
        )}

        <div className="text-center max-w-2xl mx-auto">
          <h1 className="text-5xl sm:text-7xl font-bold mb-12 tracking-tight">
            {formatTime(currentTime)}
          </h1>

          <div className="flex flex-col space-y-4 sm:space-y-6 px-4">
            <button
              onClick={handleStart}
              disabled={isProcessing || !currentShift || !userTeam}
              className="w-full py-6 sm:py-8 px-8 text-xl sm:text-2xl font-semibold
                bg-primary-600 text-white
                hover:bg-primary-700 dark:hover:bg-primary-500
                rounded-2xl shadow-lg
                disabled:opacity-50 disabled:cursor-not-allowed
                transform transition-all hover:scale-[1.02] active:scale-[0.98]
                disabled:hover:scale-100
                hover:shadow-primary-500/25 hover:shadow-xl
                focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2
                dark:focus:ring-offset-dark-900"
            >
              {isProcessing ? (
                <CircularProgress size={24} color="inherit" />
              ) : hasStartedWork ? (
                'Update Early Minutes'
              ) : (
                'Start Work'
              )}
            </button>

            <button
              onClick={() => setManualEntryOpen(true)}
              disabled={isProcessing || !currentShift || !userTeam}
              className="w-full py-6 sm:py-8 px-8 text-xl sm:text-2xl font-semibold
                border-4 border-primary-500 text-primary-600
                dark:text-primary-400 dark:border-primary-400
                hover:bg-primary-50 dark:hover:bg-dark-800/50
                rounded-2xl shadow-lg
                disabled:opacity-50 disabled:cursor-not-allowed
                transform transition-all hover:scale-[1.02] active:scale-[0.98]
                disabled:hover:scale-100
                hover:shadow-primary-500/25 hover:shadow-xl
                focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2
                dark:focus:ring-offset-dark-900"
            >
              Manual Entry
            </button>
          </div>
        </div>

        {/* Edit Minutes Dialog */}
        <MuiDialog 
          open={dialogOpen} 
          onClose={() => setDialogOpen(false)}
          PaperProps={{
            className: 'dark:bg-dark-800'
          }}
        >
          <DialogTitle className="text-gray-900 dark:text-white">
            Edit Early Minutes
          </DialogTitle>
          <DialogContent>
            <TextField
              autoFocus
              margin="dense"
              label="Early Minutes"
              type="number"
              fullWidth
              value={manualMinutes}
              onChange={(e) => setManualMinutes(e.target.value)}
              className="dark:bg-dark-700"
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSaveTime} variant="contained" color="primary">
              Save
            </Button>
          </DialogActions>
        </MuiDialog>

        {/* Manual Entry Dialog */}
        <MuiDialog 
          open={manualEntryOpen} 
          onClose={() => setManualEntryOpen(false)}
          PaperProps={{
            className: 'dark:bg-dark-800'
          }}
        >
          <DialogTitle className="text-gray-900 dark:text-white">
            Manual Time Entry
          </DialogTitle>
          <DialogContent>
            <LocalizationProvider dateAdapter={AdapterDateFns}>
              <DateTimePicker
                label="Select Date and Time"
                value={selectedDateTime}
                onChange={(newValue) => setSelectedDateTime(newValue)}
                ampm={false}
                minutesStep={1}
                renderInput={(params) => (
                  <TextField 
                    {...params} 
                    fullWidth 
                    margin="normal"
                    className="dark:bg-dark-700"
                  />
                )}
              />
            </LocalizationProvider>
          </DialogContent>
          <DialogActions>
            <Button 
              onClick={() => setManualEntryOpen(false)}
              className="text-gray-600 dark:text-gray-300"
            >
              Cancel
            </Button>
            <Button 
              onClick={handleManualEntry}
              disabled={isProcessing}
              variant="contained"
              color="primary"
            >
              {isProcessing ? 'Saving...' : 'Save Entry'}
            </Button>
          </DialogActions>
        </MuiDialog>
      </div>
    </div>
  );
}

export default Timer; 