import React, { useState, useEffect, useCallback } from 'react';
import { 
  Box, 
  Paper, 
  Typography, 
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  CircularProgress,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Select,
  MenuItem,
  FormControl,
  InputLabel
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import { db } from '../../config/firebase';
import { useAuth } from '../../contexts/AuthContext';
import { collection, query, where, getDocs, deleteDoc, doc, orderBy } from 'firebase/firestore';
import { BarChart, Bar, XAxis, YAxis, Tooltip, Legend, ResponsiveContainer, CartesianGrid } from 'recharts';
import { styled } from '@mui/material/styles';

// Styled components
const StyledPaper = styled(Paper)(({ theme }) => ({
  background: theme.palette.background.card,
  padding: theme.spacing(3),
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  transition: 'transform 0.2s ease-in-out',
  '&:hover': {
    transform: 'translateY(-4px)',
  },
}));

const StatValue = styled(Typography)(({ theme }) => ({
  color: theme.palette.primary.main,
  fontWeight: 600,
  marginTop: theme.spacing(1),
}));

const ChartContainer = styled(Box)(({ theme }) => ({
  height: 300,
  [theme.breakpoints.down('sm')]: {
    height: 250,
  },
  marginTop: theme.spacing(2),
}));

function Reports() {
  const [currentWeekOvertime, setCurrentWeekOvertime] = useState(0);
  const [historicalData, setHistoricalData] = useState([]);
  const [weeklyData, setWeeklyData] = useState([]);
  const [shiftStats, setShiftStats] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [timeEntries, setTimeEntries] = useState([]);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState(null);
  const [viewMode, setViewMode] = useState('daily');
  const { currentUser } = useAuth();

  const calculateOvertimeByShift = useCallback((entries) => {
    const overtimeData = {
      Morning: 0,
      Evening: 0,
      Night: 0
    };

    entries.forEach(entry => {
      if (entry.earlyMinutes && entry.shift) {
        // Convert minutes to hours with one decimal place
        const overtimeHours = Math.round((entry.earlyMinutes / 60) * 10) / 10;
        
        // Add overtime to the appropriate shift
        if (overtimeData.hasOwnProperty(entry.shift)) {
          overtimeData[entry.shift] += overtimeHours;
        }
      }
    });

    // Convert to array format for Recharts
    return Object.entries(overtimeData).map(([shift, hours]) => ({
      shift,
      hours: Math.round(hours * 10) / 10 // Round to 1 decimal place
    }));
  }, []);

  const processHistoricalData = useCallback((entries) => {
    // Process daily data
    const dailyData = entries.map(entry => ({
      id: entry.id,
      date: entry.date,
      time: entry.startTime?.toDate?.() || entry.date,
      shift: entry.shift,
      earlyHours: entry.earlyHours || 0,
      team: entry.team
    }));

    // Process weekly data
    const weeklyMap = new Map();
    entries.forEach(entry => {
      const date = entry.date;
      const weekKey = `${date.getFullYear()}-W${getWeekNumber(date)}`;
      
      if (!weeklyMap.has(weekKey)) {
        weeklyMap.set(weekKey, {
          weekKey,
          weekNumber: getWeekNumber(date),
          year: date.getFullYear(),
          totalHours: 0,
          entries: []
        });
      }
      
      const weekData = weeklyMap.get(weekKey);
      weekData.totalHours += entry.earlyHours || 0;
      weekData.entries.push(entry);
    });

    const weeklyData = Array.from(weeklyMap.values())
      .sort((a, b) => b.weekKey.localeCompare(a.weekKey));

    return { dailyData, weeklyData };
  }, []);

  useEffect(() => {
    const fetchTimeEntries = async () => {
      if (!currentUser) return;

      setLoading(true);
      try {
        const startDate = new Date();
        startDate.setDate(1); // First day of current month
        startDate.setHours(0, 0, 0, 0);

        const endDate = new Date();
        endDate.setHours(23, 59, 59, 999);

        const q = query(
          collection(db, 'timeEntries'),
          where('userId', '==', currentUser.uid),
          where('date', '>=', startDate),
          where('date', '<=', endDate),
          orderBy('date', 'desc')
        );

        const querySnapshot = await getDocs(q);
        const entries = querySnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data(),
          date: doc.data().date.toDate()
        }));

        setTimeEntries(entries);
        const { dailyData, weeklyData } = processHistoricalData(entries);
        setHistoricalData(dailyData);
        setWeeklyData(weeklyData);
        
        const overtimeData = calculateOvertimeByShift(entries);
        setShiftStats(overtimeData);

        // Calculate current week overtime
        const now = new Date();
        const startOfWeek = new Date(now);
        startOfWeek.setDate(now.getDate() - now.getDay());
        startOfWeek.setHours(0, 0, 0, 0);

        const weeklyTotal = entries
          .filter(entry => new Date(entry.date) >= startOfWeek)
          .reduce((total, entry) => total + (entry.earlyHours || 0), 0);

        setCurrentWeekOvertime(Math.round(weeklyTotal * 10) / 10);
        
      } catch (error) {
        console.error('Error fetching time entries:', error);
        setError('Failed to load time entries');
      } finally {
        setLoading(false);
      }
    };

    fetchTimeEntries();
  }, [currentUser, calculateOvertimeByShift, processHistoricalData]);

  const getWeekNumber = (date) => {
    const d = new Date(date);
    d.setHours(0, 0, 0, 0);
    
    // Get first day of year
    const yearStart = new Date(d.getFullYear(), 0, 1);
    
    // Get first Sunday of year
    const firstSunday = new Date(yearStart);
    firstSunday.setDate(yearStart.getDate() + (7 - yearStart.getDay()) % 7);
    
    // If date is before first Sunday, it's week 1
    if (d < firstSunday) {
      return 1;
    }
    
    // Calculate week number based on first Sunday
    const daysSinceFirstSunday = Math.floor((d - firstSunday) / (24 * 60 * 60 * 1000));
    return Math.floor(daysSinceFirstSunday / 7) + 2; // Add 2 because week 1 is before first Sunday
  };

  const handleDeleteClick = (entry) => {
    setSelectedEntry(entry);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    try {
      await deleteDoc(doc(db, 'timeEntries', selectedEntry.id));
      setTimeEntries(prev => prev.filter(entry => entry.id !== selectedEntry.id));
      setDeleteDialogOpen(false);
      setSelectedEntry(null);
      
      // Recalculate overtime data
      const overtimeData = calculateOvertimeByShift(timeEntries);
      setShiftStats(overtimeData);
    } catch (error) {
      console.error('Error deleting entry:', error);
      setError('Failed to delete entry');
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 dark:bg-dark-900 flex justify-center items-center">
        <CircularProgress />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark-900 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <Typography variant="h4" gutterBottom sx={{ mb: 4, color: 'text.primary' }}>
          Time Reports
        </Typography>

        <Grid container spacing={3}>
          <Grid item xs={12} md={6}>
            <StyledPaper elevation={3}>
              <Typography variant="h6" color="textSecondary">
                Current Week Overtime
              </Typography>
              <StatValue variant="h3">
                {currentWeekOvertime} hours
              </StatValue>
            </StyledPaper>
          </Grid>

          <Grid item xs={12}>
            <StyledPaper elevation={3}>
              <Typography variant="h6" color="textSecondary">
                Overtime by Shift
              </Typography>
              <ChartContainer>
                <ResponsiveContainer>
                  <BarChart data={shiftStats}>
                    <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
                    <XAxis dataKey="shift" stroke="#b0b0b0" />
                    <YAxis stroke="#b0b0b0" />
                    <Tooltip 
                      contentStyle={{ 
                        backgroundColor: '#1e1e1e',
                        border: '1px solid rgba(255,255,255,0.1)',
                      }}
                    />
                    <Bar dataKey="hours" fill="#90caf9" />
                  </BarChart>
                </ResponsiveContainer>
              </ChartContainer>
            </StyledPaper>
          </Grid>

          <Grid item xs={12}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="h6">Historical Data</Typography>
              <FormControl sx={{ minWidth: 120 }}>
                <InputLabel>View Mode</InputLabel>
                <Select
                  value={viewMode}
                  onChange={(e) => setViewMode(e.target.value)}
                  label="View Mode"
                >
                  <MenuItem value="daily">Daily View</MenuItem>
                  <MenuItem value="weekly">Weekly View</MenuItem>
                </Select>
              </FormControl>
            </Box>

            <Paper sx={{ p: 2 }}>
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      {viewMode === 'daily' ? (
                        <>
                          <TableCell>Date</TableCell>
                          <TableCell>Time</TableCell>
                          <TableCell>Shift</TableCell>
                          <TableCell>Early Hours</TableCell>
                          <TableCell>Team</TableCell>
                          <TableCell>Actions</TableCell>
                        </>
                      ) : (
                        <>
                          <TableCell>Week</TableCell>
                          <TableCell>Total Hours</TableCell>
                          <TableCell>Details</TableCell>
                        </>
                      )}
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {viewMode === 'daily' ? (
                      historicalData.map((entry) => (
                        <TableRow key={entry.id}>
                          <TableCell>{entry.date.toLocaleDateString()}</TableCell>
                          <TableCell>{entry.time.toLocaleTimeString()}</TableCell>
                          <TableCell>{entry.shift}</TableCell>
                          <TableCell>{entry.earlyHours}</TableCell>
                          <TableCell>{entry.team}</TableCell>
                          <TableCell>
                            <IconButton onClick={() => handleDeleteClick(entry)} size="small">
                              <DeleteIcon />
                            </IconButton>
                          </TableCell>
                        </TableRow>
                      ))
                    ) : (
                      weeklyData.map((week) => (
                        <TableRow key={week.weekKey}>
                          <TableCell>Week {week.weekNumber}, {week.year}</TableCell>
                          <TableCell>{Math.round(week.totalHours * 10) / 10}</TableCell>
                          <TableCell>
                            {week.entries.length} entries
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </Grid>
        </Grid>

        <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
          <DialogTitle>Confirm Delete</DialogTitle>
          <DialogContent>
            Are you sure you want to delete this overtime entry?
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setDeleteDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleDeleteConfirm} color="error">
              Delete
            </Button>
          </DialogActions>
        </Dialog>
      </div>
    </div>
  );
}

export default Reports; 