import React, { useState, useEffect } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import { useAuth } from '../../contexts/AuthContext';
import { db } from '../../config/firebase';
import { doc, updateDoc, getDoc } from 'firebase/firestore';

function Settings() {
  const { isDark, toggleTheme } = useTheme();
  const { currentUser } = useAuth();
  const [selectedTeam, setSelectedTeam] = useState('');
  const [selectedTimezone, setSelectedTimezone] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // List of available teams based on shift calculator
  const teams = ['A', 'B', 'C'];
  
  // Comprehensive list of world timezones
  const timezones = [
    // Africa
    'Africa/Cairo',         // Egypt
    'Africa/Casablanca',    // Morocco
    'Africa/Johannesburg',  // South Africa
    'Africa/Lagos',         // Nigeria
    'Africa/Nairobi',       // Kenya
    'Africa/Tunis',         // Tunisia

    // Americas
    'America/Anchorage',    // USA - Alaska
    'America/Bogota',       // Colombia
    'America/Buenos_Aires', // Argentina
    'America/Caracas',      // Venezuela
    'America/Chicago',      // USA - Central
    'America/Denver',       // USA - Mountain
    'America/Halifax',      // Canada - Atlantic
    'America/Lima',         // Peru
    'America/Los_Angeles',  // USA - Pacific
    'America/Mexico_City',  // Mexico
    'America/New_York',     // USA - Eastern
    'America/Phoenix',      // USA - Arizona
    'America/Santiago',     // Chile
    'America/Sao_Paulo',    // Brazil
    'America/St_Johns',     // Canada - Newfoundland
    'America/Toronto',      // Canada - Eastern
    'America/Vancouver',    // Canada - Pacific

    // Asia
    'Asia/Baghdad',         // Iraq
    'Asia/Bangkok',         // Thailand
    'Asia/Dubai',          // UAE
    'Asia/Hong_Kong',      // Hong Kong
    'Asia/Istanbul',       // Turkey
    'Asia/Jakarta',        // Indonesia
    'Asia/Jerusalem',      // Israel
    'Asia/Karachi',        // Pakistan
    'Asia/Kolkata',        // India
    'Asia/Kuwait',         // Kuwait
    'Asia/Manila',         // Philippines
    'Asia/Qatar',          // Qatar
    'Asia/Riyadh',         // Saudi Arabia
    'Asia/Seoul',          // South Korea
    'Asia/Shanghai',       // China
    'Asia/Singapore',      // Singapore
    'Asia/Taipei',         // Taiwan
    'Asia/Tehran',         // Iran
    'Asia/Tokyo',          // Japan

    // Australia & Pacific
    'Australia/Adelaide',   // South Australia
    'Australia/Brisbane',   // Queensland
    'Australia/Darwin',     // Northern Territory
    'Australia/Melbourne',  // Victoria
    'Australia/Perth',      // Western Australia
    'Australia/Sydney',     // New South Wales
    'Pacific/Auckland',     // New Zealand
    'Pacific/Fiji',        // Fiji
    'Pacific/Guam',        // Guam
    'Pacific/Honolulu',    // USA - Hawaii
    'Pacific/Samoa',       // Samoa

    // Europe
    'Europe/Amsterdam',     // Netherlands
    'Europe/Athens',       // Greece
    'Europe/Belgrade',     // Serbia
    'Europe/Berlin',       // Germany
    'Europe/Brussels',     // Belgium
    'Europe/Bucharest',    // Romania
    'Europe/Budapest',     // Hungary
    'Europe/Copenhagen',   // Denmark
    'Europe/Dublin',       // Ireland
    'Europe/Helsinki',     // Finland
    'Europe/Istanbul',     // Turkey
    'Europe/Kiev',         // Ukraine
    'Europe/Lisbon',       // Portugal
    'Europe/London',       // United Kingdom
    'Europe/Madrid',       // Spain
    'Europe/Moscow',       // Russia
    'Europe/Oslo',         // Norway
    'Europe/Paris',        // France
    'Europe/Prague',       // Czech Republic
    'Europe/Rome',         // Italy
    'Europe/Stockholm',    // Sweden
    'Europe/Vienna',       // Austria
    'Europe/Warsaw',       // Poland
    'Europe/Zurich',       // Switzerland

    // Indian Ocean
    'Indian/Maldives',     // Maldives
    'Indian/Mauritius',    // Mauritius
  ].sort();

  useEffect(() => {
    const fetchUserSettings = async () => {
      if (!currentUser) return;
      
      try {
        const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
        if (userDoc.exists()) {
          const userData = userDoc.data();
          setSelectedTeam(userData.team || '');
          setSelectedTimezone(userData.timezone || '');
        }
      } catch (error) {
        console.error('Error fetching user settings:', error);
        setError('Failed to load settings');
      }
    };

    fetchUserSettings();
  }, [currentUser]);

  const handleSaveSettings = async () => {
    if (!currentUser) return;
    
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      await updateDoc(doc(db, 'users', currentUser.uid), {
        team: selectedTeam,
        timezone: selectedTimezone,
      });
      setSuccess('Settings saved successfully');
    } catch (error) {
      console.error('Error saving settings:', error);
      setError('Failed to save settings');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark-900 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <h1 className="text-2xl font-bold text-gray-900 dark:text-white mb-8">
          Settings
        </h1>

        {error && (
          <div className="mb-4 bg-red-50 dark:bg-red-900/30 border border-red-400 
            text-red-800 dark:text-red-300 rounded-md p-3 text-sm">
            {error}
          </div>
        )}

        {success && (
          <div className="mb-4 bg-green-50 dark:bg-green-900/30 border border-green-400 
            text-green-800 dark:text-green-300 rounded-md p-3 text-sm">
            {success}
          </div>
        )}

        <div className="space-y-6">
          {/* Dark Mode Toggle */}
          <div className="bg-white dark:bg-dark-800 rounded-lg shadow">
            <div className="px-4 py-5 sm:p-6">
              <div className="flex items-center justify-between">
                <div>
                  <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">
                    Dark Mode
                  </h3>
                  <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
                    Toggle between light and dark theme
                  </p>
                </div>
                <button
                  onClick={toggleTheme}
                  className="relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer 
                    rounded-full border-2 border-transparent transition-colors duration-200 
                    ease-in-out focus:outline-none focus:ring-2 focus:ring-primary-500 
                    focus:ring-offset-2 dark:focus:ring-offset-dark-900"
                  style={{
                    backgroundColor: isDark ? '#3b82f6' : '#e5e7eb'
                  }}
                >
                  <span className="sr-only">Toggle dark mode</span>
                  <span
                    className={`pointer-events-none inline-block h-5 w-5 transform 
                      rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out
                      ${isDark ? 'translate-x-5' : 'translate-x-0'}`}
                  />
                </button>
              </div>
            </div>
          </div>

          {/* Team Selection */}
          <div className="bg-white dark:bg-dark-800 rounded-lg shadow">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">
                Shift Selection
              </h3>
              <div className="mt-2 max-w-xl">
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  Select your shift
                </p>
              </div>
              <div className="mt-5">
                <select
                  value={selectedTeam}
                  onChange={(e) => setSelectedTeam(e.target.value)}
                  className="mt-1 block w-full rounded-md border-gray-300 dark:border-dark-600 
                    dark:bg-dark-700 shadow-sm focus:border-primary-500 focus:ring-primary-500 
                    sm:text-sm dark:text-white"
                >
                  <option value="">Select a team</option>
                  {teams.map((team) => (
                    <option key={team} value={team}>
                      {team}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          {/* Timezone Selection */}
          <div className="bg-white dark:bg-dark-800 rounded-lg shadow">
            <div className="px-4 py-5 sm:p-6">
              <h3 className="text-lg font-medium leading-6 text-gray-900 dark:text-white">
                Timezone
              </h3>
              <div className="mt-2 max-w-xl">
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  Set your timezone for accurate time tracking
                </p>
              </div>
              <div className="mt-5">
                <select
                  value={selectedTimezone}
                  onChange={(e) => setSelectedTimezone(e.target.value)}
                  className="mt-1 block w-full rounded-md border-gray-300 dark:border-dark-600 
                    dark:bg-dark-700 shadow-sm focus:border-primary-500 focus:ring-primary-500 
                    sm:text-sm dark:text-white"
                >
                  <option value="">Select a timezone</option>
                  {timezones.map((timezone) => (
                    <option key={timezone} value={timezone}>
                      {timezone}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          {/* Save Button */}
          <div className="flex justify-end">
            <button
              onClick={handleSaveSettings}
              disabled={loading}
              className="btn-primary"
            >
              {loading ? 'Saving...' : 'Save Settings'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Settings; 