import React, { useState, useCallback, useEffect } from 'react';
import { Box, Typography, CircularProgress } from '@mui/material';
import { useAuth } from '../../contexts/AuthContext';
import { db } from '../../config/firebase';
import { doc, getDoc } from 'firebase/firestore';
import { getShiftRotation, SHIFTS } from '../../utils/shiftCalculator';

function Calendar() {
  const [userTeam, setUserTeam] = useState(null);
  const [loading, setLoading] = useState(true);
  const { currentUser } = useAuth();

  const fetchUserTeam = useCallback(async () => {
    try {
      const userDoc = await getDoc(doc(db, 'users', currentUser.uid));
      if (userDoc.exists()) {
        const team = userDoc.data().team;
        setUserTeam(team);
      }
      setLoading(false);
    } catch (error) {
      console.error('Error fetching user team:', error);
      setLoading(false);
    }
  }, [currentUser.uid]);

  const generateYearlySchedule = useCallback(() => {
    if (!userTeam) return [];

    const year = new Date().getFullYear();
    const months = [];
    
    for (let month = 0; month < 12; month++) {
      const daysInMonth = new Date(year, month + 1, 0).getDate();
      const monthData = [];
      
      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(year, month, day);
        const rotation = getShiftRotation(date);
        
        let shift = 'N/A';
        let startTime = '-';
        
        if (rotation && rotation[userTeam]) {
          shift = rotation[userTeam].name;
          startTime = rotation[userTeam].startTime;
        }

        monthData.push({
          date,
          shift,
          startTime,
          isWeekend: date.getDay() === 0 || date.getDay() === 6,
          isNightShift: shift === SHIFTS.NIGHT.name
        });
      }
      
      months.push({
        name: new Date(year, month).toLocaleString('default', { month: 'long' }),
        days: monthData
      });
    }
    
    return months;
  }, [userTeam]);

  useEffect(() => {
    fetchUserTeam();
  }, [fetchUserTeam]);

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <CircularProgress />
      </div>
    );
  }

  const yearlySchedule = generateYearlySchedule();

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-dark-900 p-6 sm:p-8">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-2xl sm:text-3xl font-bold text-gray-900 dark:text-white mb-6">
          Yearly Schedule - Team {userTeam}
        </h1>

        {loading ? (
          <div className="flex justify-center py-12">
            <CircularProgress />
          </div>
        ) : (
          <div className="space-y-6">
            {yearlySchedule.map((month) => (
              <div key={month.name} 
                className="bg-white dark:bg-dark-800 rounded-xl shadow-lg overflow-hidden">
                <div className="px-6 py-4 bg-primary-50 dark:bg-dark-700">
                  <h2 className="text-xl font-semibold text-primary-900 dark:text-primary-100">
                    {month.name}
                  </h2>
                </div>
                
                <div className="overflow-x-auto">
                  <table className="min-w-full divide-y divide-gray-200 dark:divide-dark-600">
                    <thead className="bg-gray-50 dark:bg-dark-800">
                      <tr>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 
                          dark:text-gray-400 uppercase tracking-wider">Date</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 
                          dark:text-gray-400 uppercase tracking-wider">Day</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 
                          dark:text-gray-400 uppercase tracking-wider">Shift</th>
                        <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 
                          dark:text-gray-400 uppercase tracking-wider">Start Time</th>
                      </tr>
                    </thead>
                    <tbody className="bg-white dark:bg-dark-800 divide-y divide-gray-200 
                      dark:divide-dark-600">
                      {month.days.map((day) => {
                        const isToday = day.date.toDateString() === new Date().toDateString();
                        const baseClasses = "px-6 py-4 whitespace-nowrap text-sm transition-colors";
                        
                        let rowClasses = "";
                        if (isToday) {
                          rowClasses = "bg-primary-50 dark:bg-primary-900/20";
                        } else if (day.isNightShift) {
                          rowClasses = "bg-indigo-50/50 dark:bg-indigo-900/20";
                        } else if (day.isWeekend) {
                          rowClasses = "bg-emerald-50/50 dark:bg-emerald-900/20";
                        }

                        return (
                          <tr 
                            key={day.date.toISOString()}
                            className={`${rowClasses} hover:bg-gray-50 
                              dark:hover:bg-dark-700/50`}
                          >
                            <td className={`${baseClasses} font-medium 
                              ${isToday ? 'text-primary-700 dark:text-primary-400' : 
                              'text-gray-900 dark:text-gray-100'}`}>
                              {day.date.toLocaleDateString()}
                            </td>
                            <td className={`${baseClasses} 
                              ${day.isWeekend ? 'text-emerald-700 dark:text-emerald-400' : 
                              'text-gray-700 dark:text-gray-300'}`}>
                              {day.date.toLocaleDateString(undefined, { weekday: 'long' })}
                            </td>
                            <td className={`${baseClasses} 
                              ${day.isNightShift ? 'text-indigo-700 dark:text-indigo-400' : 
                              'text-gray-700 dark:text-gray-300'}`}>
                              {day.shift}
                            </td>
                            <td className={`${baseClasses} text-gray-700 dark:text-gray-300`}>
                              {day.startTime}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

export default Calendar; 